Future<bool> _playWelcomeVoiceOnce() async => _speakWelcomeVoice(force: false);

Future<bool> _speakWelcomeVoice({bool force = false}) async {
  try {
    final prefs = await SharedPreferences.getInstance();
    if (!force && prefs.getBool('noor_welcome_voice_played_v8') == true) return true;
    final tts = FlutterTts();
    if (!kIsWeb && Platform.isIOS) {
      try {
        await tts.setSharedInstance(true);
        await tts.setIosAudioCategory(
          IosTextToSpeechAudioCategory.playback,
          [IosTextToSpeechAudioCategoryOptions.duckOthers],
          IosTextToSpeechAudioMode.voicePrompt,
        );
      } catch (_) {}
    }
    try { await tts.stop(); } catch (_) {}
    if (!kIsWeb && Platform.isAndroid) {
      try {
        final engines = await tts.getEngines;
        final defaultEngine = await tts.getDefaultEngine;
        if (defaultEngine != null && defaultEngine.toString().trim().isNotEmpty) {
          await tts.setEngine(defaultEngine.toString());
        } else if (engines is List && engines.isNotEmpty) {
          await tts.setEngine(engines.first.toString());
        }
        await tts.setQueueMode(0);
      } catch (_) {}
    }
    String language = 'ar-SA';
    try {
      final available = await tts.getLanguages;
      final languages = available is List ? available.map((e) => e.toString()).toList() : <String>[];
      const candidates = <String>['ar-IQ', 'ar-SA', 'ar', 'ar-AE', 'ar-EG'];
      language = candidates.firstWhere(
        (candidate) => languages.contains(candidate),
        orElse: () => languages.firstWhere(
          (e) => e.toLowerCase().startsWith('ar'),
          orElse: () => 'ar-SA',
        ),
      );
    } catch (_) {}
    try { await tts.setLanguage(language); } catch (_) {
      try { await tts.setLanguage('ar'); } catch (_) {}
    }
    try {
      final voices = await tts.getVoices;
      if (voices is List) {
        for (final voice in voices) {
          if (voice is Map) {
            final locale = '${voice['locale'] ?? ''}'.toLowerCase();
            final name = voice['name']?.toString();
            if (locale.startsWith('ar') && name != null && name.isNotEmpty) {
              await tts.setVoice({'name': name, 'locale': voice['locale'].toString()});
              break;
            }
          }
        }
      }
    } catch (_) {}
    await tts.setSpeechRate(0.40);
    await tts.setPitch(0.95);
    await tts.setVolume(1.0);
    await tts.awaitSpeakCompletion(true);
    await Future<void>.delayed(const Duration(milliseconds: 250));
    bool started = false;
    bool failed = false;
    try {
      tts.setStartHandler(() { started = true; });
      tts.setErrorHandler((_) { failed = true; });
    } catch (_) {}
    const welcomeMessage =
        'السلام عليكم ورحمة الله وبركاته. أهلاً وسهلاً بكم في نور القرآن. '
        'اجعلوا القرآن رفيق يومكم، واقرؤوا ورتّلوا القرآن ترتيلاً. '
        'نسأل الله أن يجعل هذا التطبيق نوراً في قلوبكم وحياتكم.';
    dynamic result;
    try {
      result = await tts.speak(
        welcomeMessage,
        focus: !kIsWeb && Platform.isAndroid,
      );
    } catch (_) { result = null; }
    final accepted = started || result == 1 || result == '1' || result == true;
    if (!accepted || failed) return false;
    await prefs.setBool('noor_welcome_voice_played_v8', true);
    return true;
  } catch (_) {
    return false;
  }
}

