  Map<String, String> times = {};
  Timer? _prayerRefreshTimer;
  String _lastPrayerDateKey = '';
  String _nextPrayerName = '';
  Duration _timeToNextPrayer = Duration.zero;

  // طريقة الحساب الحالية: 8 = Gulf Region.
  // لاحقًا يمكن جعلها قابلة للتغيير من الإعدادات.
  static const int calculationMethod = 8;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _loadSavedLocation();
    _prayerRefreshTimer = Timer.periodic(const Duration(seconds: 20), (_) => _updatePrayerClockAndDate());
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted) {
      _updatePrayerClockAndDate();
      _getCurrentLocation();
    }
  }

  @override
  void dispose() {
    _prayerRefreshTimer?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  String _prayerDateKey() {
    final now = DateTime.now();
    return '${now.year}-${now.month}-${now.day}';
  }

  DateTime? _todayTime(String value) {
    final m = RegExp(r'^(\d{1,2}):(\d{2})').firstMatch(value.trim());
    if (m == null) return null;
    final h = int.tryParse(m.group(1)!);
    final min = int.tryParse(m.group(2)!);
    if (h == null || min == null) return null;
    final now = DateTime.now();
    return DateTime(now.year, now.month, now.day, h, min);
  }

  void _updatePrayerClockAndDate() {
    if (!mounted) return;
    final now = DateTime.now();
    final todayKey = _prayerDateKey();
    if (_lastPrayerDateKey.isNotEmpty && _lastPrayerDateKey != todayKey && latitude != null && longitude != null && !loading) {
      _loadPrayerTimes();
      return;
    }
    if (times.isEmpty) return;
    const ordered = <String>['الفجر', 'الشروق', 'الظهر', 'العصر', 'المغرب', 'العشاء'];
    for (final name in ordered) {
      final dt = _todayTime(times[name] ?? '');
      if (dt != null && dt.isAfter(now)) {
        setState(() {
          _nextPrayerName = name;
          _timeToNextPrayer = dt.difference(now);
        });
        return;
      }
    }
    final fajr = _todayTime(times['الفجر'] ?? '');
    if (fajr != null) {
      final tomorrow = fajr.add(const Duration(days: 1));
      setState(() {
        _nextPrayerName = 'الفجر';
        _timeToNextPrayer = tomorrow.difference(now);
      });
    }
  }

  String _formatCountdown(Duration d) {
    final h = d.inHours;
    final m = d.inMinutes.remainder(60);
    final s = d.inSeconds.remainder(60);
    return '${h.toString().padLeft(2, '0')}:${m.toString().padLeft(2, '0')}:${s.toString().padLeft(2, '0')}';
  }

  Future<void> _loadSavedLocation() async {
    final prefs = await SharedPreferences.getInstance();
    final savedLat = prefs.getDouble('noor_prayer_latitude');
    final savedLon = prefs.getDouble('noor_prayer_longitude');
    final savedLocation = prefs.getString('noor_prayer_location');

    if (savedLat != null && savedLon != null && mounted) {
      setState(() {
        latitude = savedLat;
        longitude = savedLon;
        locationText = savedLocation ?? 'آخر موقع محفوظ';
        locationReady = true;
      });
      await _loadPrayerTimes();
    } else {
      await _getCurrentLocation();
    }
  }

  Future<void> _getCurrentLocation() async {
    setState(() {
      loading = true;
      error = null;
    });

    try {
      final serviceEnabled = await Geolocator.isLocationServiceEnabled();
      if (!serviceEnabled) {
        if (!mounted) return;
        setState(() {
          loading = false;
          error = 'خدمة الموقع (GPS) غير مفعّلة. فعّلي الموقع من إعدادات الجهاز ثم حاولي مرة أخرى.';
        });
        return;
      }

      // إذا كانت صفحة القبلة قد حصلت على GPS بنجاح، استخدم نفس الإحداثيات فوراً.
      // هذا يمنع إعادة انتظار GPS مرة ثانية ويجعل المواقيت والقبلة متسقتين.
      final shared = await SharedPreferences.getInstance();
      final qiblaLat = shared.getDouble('noor_qibla_latitude');
      final qiblaLon = shared.getDouble('noor_qibla_longitude');
      if (qiblaLat != null && qiblaLon != null) {
        latitude = qiblaLat;
        longitude = qiblaLon;
        locationText = 'الموقع الحالي • ${qiblaLat.toStringAsFixed(4)}°، ${qiblaLon.toStringAsFixed(4)}°';
        locationReady = true;
        await shared.setDouble('noor_prayer_latitude', qiblaLat);
        await shared.setDouble('noor_prayer_longitude', qiblaLon);
        await shared.setString('noor_prayer_location', locationText);
        if (mounted) setState(() {});
        await _loadPrayerTimes();
        return;
      }

      var permission = await Geolocator.checkPermission();

      if (permission == LocationPermission.denied) {
        permission = await Geolocator.requestPermission();
      }

      if (permission == LocationPermission.denied) {
        if (!mounted) return;
        setState(() {
          loading = false;
          error = 'تم رفض إذن الموقع. نحتاج الموقع فقط لحساب مواقيت الصلاة حسب مكانك.';
        });
        return;
      }

      if (permission == LocationPermission.deniedForever) {
        if (!mounted) return;
        setState(() {
          loading = false;
          error = 'إذن الموقع مرفوض نهائيًا. افتحي إعدادات التطبيق وفعّلي صلاحية الموقع.';
        });
        return;
      }

      Position? position;

      // مواقيت الصلاة لا تحتاج دقة مترية؛ الدقة المتوسطة أسرع وأكثر
      // استقراراً على الأجهزة التي تتأخر في الحصول على GPS.
      try {
        position = await Geolocator.getCurrentPosition(
          locationSettings: const LocationSettings(
            accuracy: LocationAccuracy.medium,
            distanceFilter: 0,
          ),
        ).timeout(const Duration(seconds: 12));
      } catch (_) {
        // إذا لم يصل GPS بسرعة، استخدم آخر موقع معروف للجهاز مؤقتاً.
        position = await Geolocator.getLastKnownPosition();
      }

      if (position == null) {
        final prefsFallback = await SharedPreferences.getInstance();
        final savedQiblaLat = prefsFallback.getDouble('noor_qibla_latitude');
        final savedQiblaLon = prefsFallback.getDouble('noor_qibla_longitude');
        if (savedQiblaLat != null && savedQiblaLon != null) {
          latitude = savedQiblaLat;
          longitude = savedQiblaLon;
          locationText = 'آخر موقع GPS محفوظ • ${savedQiblaLat.toStringAsFixed(4)}°، ${savedQiblaLon.toStringAsFixed(4)}°';
          locationReady = true;
          await prefsFallback.setDouble('noor_prayer_latitude', savedQiblaLat);
          await prefsFallback.setDouble('noor_prayer_longitude', savedQiblaLon);
          await prefsFallback.setString('noor_prayer_location', locationText);
          if (mounted) setState(() {});
          await _loadPrayerTimes();
          return;
        }
        throw Exception('NO_LOCATION_FIX');
      }

      latitude = position.latitude;
      longitude = position.longitude;
      locationText =
          'الموقع الحالي • ${position.latitude.toStringAsFixed(4)}°، ${position.longitude.toStringAsFixed(4)}°';
      locationReady = true;

      final prefs = await SharedPreferences.getInstance();
      await prefs.setDouble('noor_prayer_latitude', position.latitude);
      await prefs.setDouble('noor_prayer_longitude', position.longitude);
      await prefs.setString('noor_prayer_location', locationText);

      if (mounted) {
        setState(() {});
      }

      await _loadPrayerTimes();
    } catch (e) {
      if (!mounted) return;
      setState(() {
        loading = false;
        error = 'لم نحصل على إحداثيات GPS بعد. فعّلي الموقع واسمحي للتطبيق بالموقع الدقيق، ثم اضغطي تحديث موقعي مرة أخرى.';
      });
    }
  }

  Future<void> _loadPrayerTimes() async {
    if (latitude == null || longitude == null) {
      await _getCurrentLocation();
      return;
    }

    setState(() {
      loading = true;
      error = null;
    });

    try {
      final now = DateTime.now();
      final date =
          '${now.day.toString().padLeft(2, '0')}-${now.month.toString().padLeft(2, '0')}-${now.year}';

      final url = Uri.parse(
        'https://api.aladhan.com/v1/timings/$date'
        '?latitude=$latitude'
        '&longitude=$longitude'
        '&method=$calculationMethod',
      );

      final response = await http.get(url).timeout(
            const Duration(seconds: 15),
          );

      if (response.statusCode != 200) {
        throw Exception('HTTP ${response.statusCode}');
      }

      final body = jsonDecode(response.body) as Map<String, dynamic>;
      final data = body['data'] as Map<String, dynamic>;
      final timings = Map<String, dynamic>.from(data['timings'] as Map);

      final metaDate = data['date'] as Map<String, dynamic>?;

      if (!mounted) return;

      setState(() {
        times = {
          'الفجر': timings['Fajr']?.toString() ?? '--:--',
          'الشروق': timings['Sunrise']?.toString() ?? '--:--',
          'الظهر': timings['Dhuhr']?.toString() ?? '--:--',
          'العصر': timings['Asr']?.toString() ?? '--:--',
          'المغرب': timings['Maghrib']?.toString() ?? '--:--',
          'العشاء': timings['Isha']?.toString() ?? '--:--',
        };

        dateText =
            '${metaDate?['gregorian']?['date'] ?? ''}  •  ${metaDate?['hijri']?['date'] ?? ''} هـ';
        _lastPrayerDateKey = _prayerDateKey();
        loading = false;
        locationReady = true;
      });
      _updatePrayerClockAndDate();
    } catch (_) {
      if (!mounted) return;
      setState(() {
        loading = false;
        error = 'تعذر تحميل مواقيت الصلاة. تحققي من اتصال الإنترنت وحاولي مرة أخرى.';
      });
    }
  }

  Future<List<Map<String, dynamic>>> _loadIraqGeoHierarchy() async {
    final response = await http.get(Uri.parse(_iraqGeoDataUrl)).timeout(
      const Duration(seconds: 12),
    );
    if (response.statusCode != 200) {
      throw Exception('HTTP ${response.statusCode}');
    }
    final decoded = jsonDecode(response.body) as Map<String, dynamic>;
    final provinces = decoded['provinces'];
    if (provinces is! List) throw Exception('Invalid Iraq geography data');
    return provinces
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .toList();
  }

  String _placeArabicName(Map<String, dynamic> item) {
    final value = item['arbName'];
    return value?.toString().trim() ?? '';
  }

  List<Map<String, dynamic>> _childrenOf(
    Map<String, dynamic> item,
    String key,
  ) {
    final raw = item[key];
    if (raw is! List) return <Map<String, dynamic>>[];
    return raw
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .where((e) => _placeArabicName(e).isNotEmpty)
        .toList();
  }

  Future<List<double>?> _geocodeIraqPlace(_IraqPlaceSelection selection) async {
    final query = <String>[
      if (selection.village != null) selection.village!,
      if (selection.subdistrict != null) selection.subdistrict!,
      if (selection.district != null) selection.district!,
      selection.governorate,
      'Iraq',
    ].join(', ');

    try {
      final uri = Uri.https(
        'nominatim.openstreetmap.org',
        '/search',
        <String, String>{
          'q': query,
          'format': 'jsonv2',
          'limit': '1',
          'countrycodes': 'iq',
          'accept-language': 'ar',
        },
      );
      final response = await http.get(uri, headers: const {
        'User-Agent': 'NoorAlQuran/1.0 (prayer-location)',
      }).timeout(const Duration(seconds: 10));

      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        if (data is List && data.isNotEmpty && data.first is Map) {
          final first = Map<String, dynamic>.from(data.first as Map);
          final lat = double.tryParse(first['lat']?.toString() ?? '');
          final lon = double.tryParse(first['lon']?.toString() ?? '');
          if (lat != null && lon != null) return [lat, lon];
        }
      }
    } catch (_) {}

    return _iraqGovernorateCoordinates[selection.governorate];
  }

  Future<void> _chooseIraqCity() async {
    List<Map<String, dynamic>> provinces;
    try {
      provinces = await _loadIraqGeoHierarchy();
    } catch (_) {
      // إذا تعذر تنزيل قاعدة البيانات، نبقي الاختيار متاحًا على مستوى المحافظة.
      provinces = _iraqGovernorateCoordinates.keys
          .map((name) => <String, dynamic>{
                'arbName': name,
                'districts': <dynamic>[],
              })
          .toList();
    }

    if (!mounted) return;

    final selection = await showModalBottomSheet<_IraqPlaceSelection>(
      context: context,
      isScrollControlled: true,
      backgroundColor: const Color(0xFFFFFCF5),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: TextDirection.rtl,
        child: _IraqLocationPickerSheet(provinces: provinces),
      ),
    );

    if (selection == null || !mounted) return;

    setState(() {
      loading = true;
      error = null;
      locationText = 'جاري تحديد الإحداثيات…';
    });

    final coords = await _geocodeIraqPlace(selection);
    if (coords == null) {
      if (!mounted) return;
      setState(() {
        loading = false;
        error = 'تعذر تحديد إحداثيات الموقع المختار. اختاري موقعًا أقرب أو استخدمي GPS.';
      });
      return;
    }

    final prefs = await SharedPreferences.getInstance();
    latitude = coords[0];
    longitude = coords[1];
    locationText = 'موقع يدوي • ${selection.label}';
    locationReady = true;

    await prefs.setDouble('noor_prayer_latitude', coords[0]);
    await prefs.setDouble('noor_prayer_longitude', coords[1]);
    await prefs.setString('noor_prayer_location', locationText);
    await prefs.setString('noor_prayer_governorate', selection.governorate);
    await prefs.setString('noor_prayer_district', selection.district ?? '');
    await prefs.setString('noor_prayer_subdistrict', selection.subdistrict ?? '');
    await prefs.setString('noor_prayer_village', selection.village ?? '');

    if (mounted) setState(() {});
    await _loadPrayerTimes();
  }

  Future<void> _refreshLocationAndTimes() async {
    await _getCurrentLocation();
  }

