    final compassReady = _deviceHeading != null && !kIsWeb;

    return Scaffold(
      backgroundColor: const Color(0xFFF7F4EC),
      appBar: AppBar(
        title: const Text('القبلة', style: TextStyle(fontWeight: FontWeight.w800)),
        centerTitle: true,
